    @Test void dataByPatternRootIdReplacesOnlyPatternScopeAndCreatesConnectedRoles(){
        call("deposit.create.class","Specimen",m("descriptors",List.of(m("name","Code","type","String"),m("name","RemoveMe","type","String"),m("name","Unknown","type","String"),m("name","Outside","type","String"))),token);
        call("deposit.create.class","Child",m("descriptors",List.of(m("name","Label","type","String"))),token);
        String root=id(call("deposit.create.object","Specimen",m("descriptors",m("Code","old","RemoveMe","remove","Unknown","unknown","Outside","preserve")),token));
        String removedTarget=id(call("deposit.create.object","Child",m("descriptors",m("Label","old")),token));
        String retainedTarget=id(call("deposit.create.object","Child",m("descriptors",m("Label","retained")),token));
        call("deposit.create.relationship",root,removedTarget,"hasChild",m(),token);call("deposit.create.relationship",root,retainedTarget,"other",m(),token);
        var definition=m("objects",m("specimen",m("className","Specimen","root",true,"descriptors",List.of(m("name","Code"),m("name","RemoveMe"),m("name","Unknown")),"relationships",List.of(m("label","hasChild","targetName","child"))),"child",m("className","Child","descriptors",List.of(m("name","Label")))));
        call("deposit.create.pattern","SpecimenForm",definition,m(),token);long before=sequence(namespace);
        var data=call("deposit.import.dataByPattern","SpecimenForm",m("specimen",m("Code","new","Unknown",null),"child",m("Label","new child")),m("rootId",root),token).get("data");String plan=data.get("planId").asString();
        assertEquals(before,sequence(namespace));assertEquals(0L,query("MATCH (:DepositImportPlan {id:$id})-[:IMPORT_OBJECT]->(:Object) RETURN count(*) AS n",m("id",plan)).getFirst().get("n").asLong());
        long objectsBefore=query("MATCH (o:Object {namespaceId:$ns}) RETURN count(o) AS n",m("ns",namespace)).getFirst().get("n").asLong();var applied=call("deposit.import.apply",plan,token).get("data");assertEquals(2L,applied.get("createdObjects").asLong(),"The result maps both Pattern roles, including the already-bound root");assertEquals(objectsBefore+1,query("MATCH (o:Object {namespaceId:$ns}) RETURN count(o) AS n",m("ns",namespace)).getFirst().get("n").asLong(),"rootId creates only the non-root Pattern role");
        assertEquals("new",query("MATCH (:Object {id:$id})-[:HAS_DESCRIPTOR]->(d:Descriptor {name:'Code'}) RETURN d.value AS value",m("id",root)).getFirst().get("value").asString());
        assertEquals(0L,query("MATCH (:Object {id:$id})-[:HAS_DESCRIPTOR]->(:Descriptor {name:'RemoveMe'}) RETURN count(*) AS n",m("id",root)).getFirst().get("n").asLong());
        assertNull(query("MATCH (:Object {id:$id})-[:HAS_DESCRIPTOR]->(d:Descriptor {name:'Unknown'}) RETURN d.value AS value",m("id",root)).getFirst().get("value").asObject());
        assertEquals("preserve",query("MATCH (:Object {id:$id})-[:HAS_DESCRIPTOR]->(d:Descriptor {name:'Outside'}) RETURN d.value AS value",m("id",root)).getFirst().get("value").asString());
        assertEquals(0L,query("MATCH (:Object {id:$root})-[:RELATED_TO {label:'hasChild'}]->(:Object {id:$target}) RETURN count(*) AS n",m("root",root,"target",removedTarget)).getFirst().get("n").asLong());
        assertEquals(1L,query("MATCH (:Object {id:$root})-[:RELATED_TO {label:'other'}]->(:Object {id:$target}) RETURN count(*) AS n",m("root",root,"target",retainedTarget)).getFirst().get("n").asLong());
        assertEquals(1L,query("MATCH (:Object {id:$root})-[:RELATED_TO {label:'hasChild'}]->(child:Object)-[:HAS_DESCRIPTOR]->(:Descriptor {name:'Label',value:'new child'}) RETURN count(DISTINCT child) AS n",m("root",root)).getFirst().get("n").asLong());
        assertEquals(1L,query("MATCH (:Object {id:$target}) RETURN count(*) AS n",m("target",removedTarget)).getFirst().get("n").asLong());
        assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.import.dataByPattern","SpecimenForm",m("specimen",m("Outside","tamper")),m("rootId",root),token),"Form values outside the stored Pattern must be rejected");
        long beforeWrongRoot=sequence(namespace),plans=query("MATCH (p:DepositImportPlan {namespaceId:$ns}) RETURN count(p) AS n",m("ns",namespace)).getFirst().get("n").asLong();var wrongRoot=assertThrows(org.neo4j.driver.exceptions.Neo4jException.class,()->call("deposit.import.dataByPattern","SpecimenForm",m(),m("rootId",removedTarget),token));assertTrue(wrongRoot.getMessage().contains("IMPORT_CONFLICT"),wrongRoot.getMessage());assertFalse(wrongRoot.getMessage().contains("planId"),wrongRoot.getMessage());assertEquals(beforeWrongRoot,sequence(namespace));assertEquals(plans,query("MATCH (p:DepositImportPlan {namespaceId:$ns}) RETURN count(p) AS n",m("ns",namespace)).getFirst().get("n").asLong());
    }
