    @Test void queryExportUsesTypedQueryRowsAndPublishesDownloadableCsv()throws Exception{
        call("deposit.create.class","Specimen",m("descriptors",List.of(m("name","Code","type","String"))),token);call("deposit.create.object","Specimen",m("descriptors",m("Code","Q-1")),token);
        var outcome=call("deposit.save.csv",m("query","SELECT Specimen.Code"),m(),m("filename","query.csv"),token).get("data");assertEquals("query.csv",outcome.get("filename").asString());assertEquals("text/csv; charset=utf-8",outcome.get("mediaType").asString());
        var chunk=call("deposit.resource.downloadChunk",outcome.get("resourceId").asString(),0L,outcome.get("bytes").asLong(),token).get("data");String content=new String(Base64.getDecoder().decode(chunk.get("bytesBase64").asString()),StandardCharsets.UTF_8);assertEquals("Specimen.Code\r\nQ-1\r\n",content);
        String payload="x".repeat(30_000);for(int i=0;i<210;i++)call("deposit.create.object","Specimen",m("descriptors",m("Code",String.format(Locale.ROOT,"Q-%04d-%s",i,payload))),token);
        var large=call("deposit.save.csv",m("query","SELECT Specimen.Code AS code ORDER BY code"),m(),m("filename","many-rows.csv"),token).get("data");String largeCsv=downloadText(large.get("resourceId").asString(),large.get("bytes").asLong(),token);assertEquals(212L,largeCsv.lines().count());assertTrue(largeCsv.startsWith("code\r\nQ-0000-"));assertTrue(largeCsv.endsWith("Q-1\r\n"));
        String racerName="export-racer-"+UUID.randomUUID();String racerUser=call("deposit.create.user",racerName,PASSWORD,m(),token).get("data").get("id").asString();call("deposit.set.namespaceRole",m("id",racerUser),"editor",token);String racerToken=call("deposit.utils.login",racerName,PASSWORD).get("value").asString();call("deposit.set.activeNamespace",m("id",namespace),racerToken);
        var resourcesBefore=query("MATCH (r:DResource {namespaceId:$ns}) RETURN count(r) AS n",m("ns",namespace)).getFirst().get("n").asLong();var grantsBefore=query("MATCH (g:DepositExportGrant {namespaceId:$ns}) RETURN count(g) AS n",m("ns",namespace)).getFirst().get("n").asLong();var receiptsBefore=query("MATCH (r:DepositReceipt {scope:$ns}) RETURN count(r) AS n",m("ns",namespace)).getFirst().get("n").asLong();java.nio.file.Path exportDirectory=exportStagingDirectory();Set<String> stagingBefore=stagedExportNames(exportDirectory);
        armExportPause("query-export-before-lock","pause");
        var export=java.util.concurrent.CompletableFuture.supplyAsync(()->call("deposit.save.xlsx",m("query","SELECT Specimen.Code AS code ORDER BY code"),m(),m("filename","raced.xlsx"),token));
        try{assertTrue(awaitExportPause(java.time.Duration.ofSeconds(30)),"Query export did not reach the pre-lock revision check");long revisionBeforeMutation=sequence(namespace);call("deposit.create.class","ConcurrentExportMutation",m(),racerToken);assertEquals(revisionBeforeMutation+1,sequence(namespace),"The independent editor must commit a Namespace revision change");}catch(InterruptedException e){Thread.currentThread().interrupt();fail("Interrupted while racing query export revision");}finally{armExportPause("","clear");}
        var failure=assertThrows(java.util.concurrent.ExecutionException.class,()->export.get(45,java.util.concurrent.TimeUnit.SECONDS));assertTrue(failure.getCause().getMessage().contains("REVISION_CONFLICT"),failure.getCause().toString());
        assertEquals(resourcesBefore,query("MATCH (r:DResource {namespaceId:$ns}) RETURN count(r) AS n",m("ns",namespace)).getFirst().get("n").asLong());assertEquals(grantsBefore,query("MATCH (g:DepositExportGrant {namespaceId:$ns}) RETURN count(g) AS n",m("ns",namespace)).getFirst().get("n").asLong());assertEquals(receiptsBefore+1,query("MATCH (r:DepositReceipt {scope:$ns}) RETURN count(r) AS n",m("ns",namespace)).getFirst().get("n").asLong(),"Only the concurrent editor mutation may create a receipt");assertEquals(stagingBefore,stagedExportNames(exportDirectory),"Failed query export must remove its staging files");
        long revisionBeforeLockedMutation=sequence(namespace);armExportPause("query-export-after-lock","pause");var lockedExport=java.util.concurrent.CompletableFuture.supplyAsync(()->call("deposit.save.xlsx",m("query","SELECT Specimen.Code AS code ORDER BY code"),m(),m("filename","locked-race.xlsx"),token));java.util.concurrent.CompletableFuture<org.neo4j.driver.Record> lockedMutation=null;
        try{assertTrue(awaitExportPause(java.time.Duration.ofSeconds(30)),"Query export did not reach the post-lock boundary");lockedMutation=java.util.concurrent.CompletableFuture.supplyAsync(()->call("deposit.create.class","AfterLockMutation",m(),racerToken));try{Thread.sleep(250);}catch(InterruptedException e){Thread.currentThread().interrupt();fail("Interrupted while checking the Namespace lock");}assertFalse(lockedMutation.isDone(),"A Namespace writer must wait while export holds its lock");}catch(InterruptedException e){Thread.currentThread().interrupt();fail("Interrupted while checking the Namespace lock");}finally{armExportPause("","clear");}
        assertNotNull(lockedExport.get(45,java.util.concurrent.TimeUnit.SECONDS));assertNotNull(lockedMutation.get(45,java.util.concurrent.TimeUnit.SECONDS));assertEquals(revisionBeforeLockedMutation+1,sequence(namespace));assertEquals(resourcesBefore+1,query("MATCH (r:DResource {namespaceId:$ns}) RETURN count(r) AS n",m("ns",namespace)).getFirst().get("n").asLong());assertEquals(grantsBefore+1,query("MATCH (g:DepositExportGrant {namespaceId:$ns}) RETURN count(g) AS n",m("ns",namespace)).getFirst().get("n").asLong());
    }
    private static String downloadText(String resource,long bytes,String token){try(var output=new ByteArrayOutputStream()){for(long offset=0;offset<bytes;){long length=Math.min(1_048_576L,bytes-offset);var chunk=call("deposit.resource.downloadChunk",resource,offset,length,token).get("data");byte[] part=Base64.getDecoder().decode(chunk.get("bytesBase64").asString());assertEquals(length,part.length);output.write(part);offset+=length;}return output.toString(StandardCharsets.UTF_8);}catch(java.io.IOException e){throw new AssertionError(e);}}
    private static java.nio.file.Path exportStagingDirectory(){try{var config=new java.util.Properties();try(var input=java.nio.file.Files.newInputStream(java.nio.file.Path.of("C:/data_processed/Deposit_v2/stage0/runs/stage0-host/neo4j/conf/deposit.properties"))){config.load(input);}return java.nio.file.Path.of(config.getProperty("resourceRoot")).resolve("staging/exports");}catch(Exception e){throw new AssertionError("Cannot locate Stage 0 export staging directory",e);}}
    private static Set<String> stagedExportNames(java.nio.file.Path directory){try(var files=java.nio.file.Files.list(directory)){return files.map(path->path.getFileName().toString()).collect(java.util.stream.Collectors.toCollection(TreeSet::new));}catch(java.io.IOException e){throw new AssertionError(e);}}
    private static void armExportPause(String point,String mode){call("stage0.storage.arm",point,mode);}
    private static boolean awaitExportPause(java.time.Duration timeout)throws InterruptedException{var marker=java.nio.file.Path.of("C:/data_processed/Deposit_v2/stage0/runs/stage0-host/stage4-pause.json");long deadline=System.nanoTime()+timeout.toNanos();while(System.nanoTime()<deadline){if(java.nio.file.Files.exists(marker))return true;Thread.sleep(10);}return false;}
